-- user-settings.lua — GENERATED by quickshell's settings app (Apply).
-- Hand edits are overwritten by the next Apply; hyprland.lua
-- require()s this file last, so these override the defaults above.
--
-- This is the full persisted snapshot from settings.json, not just the
-- last Apply diff: a diff-only file made `hyprctl reload` drop every
-- value that Apply didn't happen to touch, so the session fell back to
-- appearance.lua's stock gaps/rounding until quickshell re-applied them.
hl.config({
    general = {
        gaps_in  = 4,
        gaps_out = 10,
    },
    decoration = {
        rounding         = 8,
        active_opacity   = 1,
        inactive_opacity = 1,
        blur = {
            -- OFF on purpose. appearance.lua's 2026-10 heat retune turned
            -- this off: the 1920x560 quickshell slab (~top half of this
            -- 1080p panel) re-runs a gaussian pass on every frame it
            -- damages, which pins the HD 4600 and leaves the top of the
            -- screen unpainted. Re-enable only with Panel transparency up
            -- and the shell's qs-glass frost actually visible.
            enabled = false,
        },
    },
    input = {
        numlock_by_default = true,
        scroll_factor      = 1.4,
        touchpad = {
            natural_scroll      = false,
            clickfinger_behavior = true,
            scroll_factor        = 1.4,
        },
    },
})
